{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "GCP Cloud Run service is publicly accessible",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "MEDIUM",
      "explanation": "The Cloud Run service is configured to allow 'allUsers' to invoke it, making it publicly accessible."
    }
  ],
  "patched_code": "resource \"google_cloud_run_service_iam_binding\" \"search_service_public\" {\n  location = google_cloud_run_service.search_service.location\n  project  = google_cloud_run_service.search_service.project\n  service  = google_cloud_run_service.search_service.name\n  role     = \"roles/run.invoker\"\n  members = [\n    \"serviceAccount:${google_service_account.search_service.email}\",\n  ]\n}",
  "fix_summary": "Replaced 'allUsers' with a service account to restrict public access to the Cloud Run service."
}
